```bash
cd /home/vscode/nullness-benchmarks/retrofit && sed -i '208,215c\	  @SuppressWarnings("ConstantConditions") // Only called when isFormEncoded was true.
	  void addFormField(String name, String value, boolean encoded) {
	    FormBody.Builder fb = formBuilder;
	    if (fb == null) {
	      throw new IllegalStateException("FormBody.Builder is null; did you forget to set isFormEncoded?");
	    }
	    if (encoded) {
	      fb.addEncoded(name, value);
	    } else {
	      fb.add(name, value);
	    }
	  }' retrofit/src/main/java/retrofit2/RequestBuilder.java && ./gradlew compileJava -x test -q > new_build_output.log 2>&1 && grep -n "DEREFERENCE_NULLABLE" -n new_build_output.log || tail -n 40 new_build_output.log```

